        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static int[] Dot(this double[] rowVector, double[,] matrix, int[] result)
        {
#if DEBUG
            if (rowVector.Length != matrix.Rows() || result.Length > matrix.Columns())
                throw new DimensionMismatchException();
#endif
                        int cols = matrix.Columns();
            for (int j = 0; j < cols; j++)
            {
                int s = (int)0;
                for (int k = 0; k < rowVector.Length; k++)
                    s += (int)((int)rowVector[k] * (int)matrix[k, j]);
                result[j] = (int)s;
            }
            return result;
        }

        /// <summary>
        ///   Multiplies a matrix <c>A</c> and a column vector <c>v</c>,
        ///   giving the product <c>A*v</c>
        /// </summary>
        /// 
        /// <param name="matrix">The matrix <c>A</c>.</param>
        /// <param name="columnVector">The column vector <c>v</c>.</param>
        /// <param name="result">The matrix <c>R</c> to store the product.</param>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static int[] Dot(this double[][] matrix, double[] columnVector, int[] result)
        {
#if DEBUG
            if (matrix.Columns() != columnVector.Length || result.Length > matrix.Length)
                throw new DimensionMismatchException();
#endif

            for (int i = 0; i < matrix.Length; i++)
            {
                int s = (int)0;
                for (int j = 0; j < columnVector.Length; j++)
                    s += (int)((int)matrix[i][j] * (int)columnVector[j]);
                result[i] = (int)s;
            }
            return result;
        }

        /// <summary>
        ///   Multiplies a matrix <c>A</c> and a column vector <c>v</c>,
        ///   giving the product <c>A*v</c>
        /// </summary>
        /// 
        /// <param name="matrix">The matrix <c>A</c>.</param>
        /// <param name="columnVector">The column vector <c>v</c>.</param>
        /// <param name="result">The matrix <c>R</c> to store the product.</param>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static int[] Dot(this double[,] matrix, double[] columnVector, int[] result)
        {
            int cols = matrix.Columns();
            int rows = matrix.Rows();

#if DEBUG
            if (cols != columnVector.Length || result.Length > rows)
                throw new DimensionMismatchException();
#endif
			{
				Span<double> a = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, double>(ref MemoryMarshal.GetArrayDataReference((Array)matrix)), matrix.Length);
				Span<double> x = columnVector;
				Span<int> r = result;
				{
					int pa1 = 0;
					int pa2 = cols;
					int pr = 0;

					// Process rows two at a time
					for (int i = 0; i < rows / 2; i++)
					{
						int sum1 = 0, sum2 = 0;
						int px = 0;

						for (int j = 0; j < cols; j++)
						{
							sum1 += (int)((int)(a[pa1++]) * (int)(x[px]));
							sum2 += (int)((int)(a[pa2++]) * (int)(x[px]));
							px++;
						}

						r[pr++] = (int)sum1;
						r[pr++] = (int)sum2;
                    
						// Now we skip a row
						pa1 = pa2;
						pa2 += cols;
					}

					// Process the remainder
					for (int i = 0; i < rows % 2; i++)
					{
						int sum = 0;
						int px = 0;

						for (int j = 0; j < cols; j++)
							sum += (int)((int)(a[pa1++]) * (int)(x[px++]));

						r[pr] = (int)sum;
					}
				}
			}

            return result;
        }

