        /// <summary>
        ///   Gets the outer product (matrix product) between two vectors (a*bT).
        /// </summary>
        /// 
        /// <remarks>
        ///   In linear algebra, the outer product typically refers to the tensor
        ///   product of two vectors. The result of applying the outer product to
        ///   a pair of vectors is a matrix. The name contrasts with the inner product,
        ///   which takes as input a pair of vectors and produces a scalar.
        /// </remarks>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static float[,] Outer(this float[] a, float[] b, float[,] result)
        {
			{
				Span<float> R = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, float>(ref MemoryMarshal.GetArrayDataReference((Array)result)), result.Length);
				{
					int pr = 0;
					for (int i = 0; i < a.Length; i++)
					{
						double x = (double)a[i];
						for (int j = 0; j < b.Length; j++)
							R[pr++] = (float)(x * (double)b[j]);
					}
				}
			}
            
            return result;
        }

        /// <summary>
        ///   Gets the outer product (matrix product) between two vectors (a*bT).
        /// </summary>
        /// 
        /// <remarks>
        ///   In linear algebra, the outer product typically refers to the tensor
        ///   product of two vectors. The result of applying the outer product to
        ///   a pair of vectors is a matrix. The name contrasts with the inner product,
        ///   which takes as input a pair of vectors and produces a scalar.
        /// </remarks>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static float[][] Outer(this float[] a, float[] b, float[][] result)
        {
            for (int i = 0; i < a.Length; i++)
                for (int j = 0; j < b.Length; j++)
                    result[i][j] = (float)((double)a[i] * (double)b[j]);
            return result;
        }

        /// <summary>
        ///   Vector product.
        /// </summary>
        /// 
        /// <remarks>
        ///   The cross product, vector product or Gibbs vector product is a binary operation
        ///   on two vectors in three-dimensional space. It has a vector result, a vector which
        ///   is always perpendicular to both of the vectors being multiplied and the plane
        ///   containing them. It has many applications in mathematics, engineering and physics.
        /// </remarks>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static float[] Cross(this float[] a, float[] b, float[] result)
        {
            result[0] = (float)((double)a[1]*(double)b[2] - (double)a[2]*(double)b[1]);
            result[1] = (float)((double)a[2]*(double)b[0] - (double)a[0]*(double)b[2]);
			result[2] = (float)((double)a[0]*(double)b[1] - (double)a[1]*(double)b[0]);

			return result;
        }






#region Kronecker

        /// <summary>
        ///   Computes the Kronecker product between two matrices.
        /// </summary>
        /// 
        /// <param name="a">The left matrix a.</param>
        /// <param name="b">The right matrix b.</param>
        /// <param name="result">The matrix <c>R</c> to store the 
        ///   Kronecker product between matrices <c>A</c> and <c>B</c>.</param>
        /// 
        /// <returns>The Kronecker product of the two matrices.</returns>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static float[,] Kronecker(this float[,] a, float[,] b, float[,] result)
        {
            int arows = a.Rows();
            int acols = a.Columns();

            int brows = b.Rows();
            int bcols = b.Columns();

            //int crows = arows * brows;
            int ccols = acols * bcols;
            int block = brows * ccols;

            {
                Span<float> ptrR = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, float>(ref MemoryMarshal.GetArrayDataReference((Array)result)), result.Length);
                Span<float> ptrA = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, float>(ref MemoryMarshal.GetArrayDataReference((Array)a)), a.Length);
                Span<float> ptrB = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, float>(ref MemoryMarshal.GetArrayDataReference((Array)b)), b.Length);
                {
                    int A = 0;
                    int Ri = 0;

                    for (int i = 0; i < arows; Ri += block, i++)
                    {
                        int Rj = Ri;

                        for (int j = 0; j < acols; j++, Rj += bcols, A++)
                        {
                            int R = Rj;
                            int B = 0;

                            for (int k = 0; k < brows; k++, R += ccols)
                            {
                                for (int l = 0; l < bcols; l++, B++)
                                    ptrR[R + l] = (float)((double)(ptrA[A]) * (double)(ptrB[B]));
                            }
                        }
                    }
                }
            }

            return result;
        }

        /// <summary>
        ///   Computes the Kronecker product between two matrices.
        /// </summary>
        /// 
        /// <param name="a">The left matrix a.</param>
        /// <param name="b">The right matrix b.</param>
        /// <param name="result">The matrix <c>R</c> to store the 
        ///   Kronecker product between matrices <c>A</c> and <c>B</c>.</param>
