#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static double[][] Kronecker(this float[,] a, float[][] b, double[][] result)
        {
            int arows = a.Rows();
            int acols = a.Columns();
            int brows = b.Rows();
            int bcols = b.Columns();

            for (int i = 0; i < arows; i++)
                for (int j = 0; j < acols; j++)
				{
					double aval = (double)a[i, j];
				    for (int k = 0; k < brows; k++)
					{
						float[] brow = b[k];
					    for (int l = 0; l < bcols; l++)
                            result[i * brows + k][j * bcols + l] = (double)(aval * (double)brow[l]);
					}
				}
                
            return result;
        }

        /// <summary>
        ///   Computes the Kronecker product between two vectors.
        /// </summary>
        /// 
        /// <param name="a">The left vector a.</param>
        /// <param name="b">The right vector b.</param>
        /// <param name="result">The matrix <c>R</c> to store the 
        ///   Kronecker product between matrices <c>A</c> and <c>B</c>.</param>
        /// 
        /// <returns>The Kronecker product of the two vectors.</returns>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
		public static double[] Kronecker(this float[] a, float[] b, double[] result)
		{
			{
				Span<double> R = result;
				{
					int pr = 0;
					for (int i = 0; i < a.Length; i++)
					{
						double x = (double)a[i];
						for (int j = 0; j < b.Length; j++)
							R[pr++] = (double)(x * (double)b[j]);
					}
				}
			}
            
            return result;
        }

