        public static int[][] DivideByDiagonal(this float[][] a, float[] diagonal, int[][] result)
        {
            for (int i = 0; i < a.Length; i++)
                for (int j = 0; j < diagonal.Length; j++)
                    result[i][j] = (int)((double)(a[i][j]) / (double)diagonal[j]);

            return result;
        }

