                        for (int j = 0; j < p; j++, pr++)
                        {
                            int pa = n * i;

                            double s = (double)0;
                            for (int k = 0; k < n; k++)
                                s += (double)((double)(A[pa++]) * (double)(B[pb++]));
                            R[pr] = (int)s;
                        }
                    }
                }
