                throw new DimensionMismatchException();
            var C = Matrix.CreateAs(result).To<double[,]>();
            C = Dot(a.To<double[,]>(), b.ToMatrix().To<double[,]>(), C);
#endif
            int N = result.Length;
            int K = a.Columns();
            int M = result.Columns();

            var t = new int[K];

			{
				Span<float> A = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, float>(ref MemoryMarshal.GetArrayDataReference((Array)a)), a.Length);
				for (int j = 0; j < M; j++)
				{
					for (int k = 0; k < t.Length; k++)
						t[k] = b[k][j];

					int pa = 0;
					for (int i = 0; i < N; i++)
					{
						double s = (double)0;
						for (int k = 0; k < t.Length; k++)
							s += (double)((double)(A[pa++]) * (double)t[k]);
						result[i][j] = (float)s;
					}
				}
			}
#if DEBUG
            if (!Matrix.IsEqual(C, result.ToMatrix().To<double[,]>(), 1e-4))
                throw new Exception();
#endif
            return result;
        }

