                    for (int k = 0; k < arow.Length; k++)
                        sum += (long)((long)arow[k] * (long)brow[k]);
                    result[i][j] = (long)sum;
                }
            }
#if DEBUG
            if (!Matrix.IsEqual(C, result.To<double[,]>(), 1e-4))
                throw new Exception();
#endif
            return result;
        }

