#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static long[,] DivideByDiagonal(this long[,] a, long[] diagonal, long[,] result)
        {
            int rows = a.Rows();

            {
                Span<long> ptrA = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, long>(ref MemoryMarshal.GetArrayDataReference((Array)a)), a.Length);
                Span<long> ptrR = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, long>(ref MemoryMarshal.GetArrayDataReference((Array)result)), result.Length);
                {
                    int A = 0;
                    int R = 0;
                    for (int i = 0; i < rows; i++)
                        for (int j = 0; j < diagonal.Length; j++)
                            (ptrR[R++]) = (long)((long)(ptrA[A++]) / (long)diagonal[j]);
                }
            }

            return result;
        }

