#endif
            for (int j = 0; j < result.Length; j++)
            {
                int s = (int)0;
                for (int k = 0; k < rowVector.Length; k++)
                    s += (int)((int)rowVector[k] * (int)matrix[k][j]);
                result[j] = (int)s;
            }

            return result;
