						t[k] = b[k][j];

					int pa = 0;
					for (int i = 0; i < N; i++)
					{
						int s = (int)0;
						for (int k = 0; k < t.Length; k++)
							s += (int)((int)(A[pa++]) * (int)t[k]);
						result[i][j] = (int)s;
					}
				}
