        /// </remarks>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static int[][] Outer(this long[] a, double[] b, int[][] result)
        {
            for (int i = 0; i < a.Length; i++)
                for (int j = 0; j < b.Length; j++)
                    result[i][j] = (int)((int)a[i] * (int)b[j]);
            return result;
        }

        /// <summary>
        ///   Vector product.
        /// </summary>
        /// 
        /// <remarks>
        ///   The cross product, vector product or Gibbs vector product is a binary operation
        ///   on two vectors in three-dimensional space. It has a vector result, a vector which
        ///   is always perpendicular to both of the vectors being multiplied and the plane
        ///   containing them. It has many applications in mathematics, engineering and physics.
        /// </remarks>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static int[] Cross(this long[] a, double[] b, int[] result)
        {
            result[0] = (int)((int)a[1]*(int)b[2] - (int)a[2]*(int)b[1]);
            result[1] = (int)((int)a[2]*(int)b[0] - (int)a[0]*(int)b[2]);
			result[2] = (int)((int)a[0]*(int)b[1] - (int)a[1]*(int)b[0]);

			return result;
        }






#region Kronecker

        /// <summary>
        ///   Computes the Kronecker product between two matrices.
        /// </summary>
        /// 
        /// <param name="a">The left matrix a.</param>
        /// <param name="b">The right matrix b.</param>
        /// <param name="result">The matrix <c>R</c> to store the 
        ///   Kronecker product between matrices <c>A</c> and <c>B</c>.</param>
        /// 
        /// <returns>The Kronecker product of the two matrices.</returns>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static int[,] Kronecker(this long[,] a, double[,] b, int[,] result)
        {
            int arows = a.Rows();
            int acols = a.Columns();

            int brows = b.Rows();
            int bcols = b.Columns();

            //int crows = arows * brows;
            int ccols = acols * bcols;
            int block = brows * ccols;

            {
                Span<int> ptrR = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, int>(ref MemoryMarshal.GetArrayDataReference((Array)result)), result.Length);
                Span<long> ptrA = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, long>(ref MemoryMarshal.GetArrayDataReference((Array)a)), a.Length);
                Span<double> ptrB = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, double>(ref MemoryMarshal.GetArrayDataReference((Array)b)), b.Length);
                {
                    int A = 0;
                    int Ri = 0;

                    for (int i = 0; i < arows; Ri += block, i++)
                    {
                        int Rj = Ri;

                        for (int j = 0; j < acols; j++, Rj += bcols, A++)
                        {
                            int R = Rj;
                            int B = 0;

                            for (int k = 0; k < brows; k++, R += ccols)
                            {
                                for (int l = 0; l < bcols; l++, B++)
                                    ptrR[R + l] = (int)((int)(ptrA[A]) * (int)(ptrB[B]));
                            }
                        }
                    }
                }
            }

            return result;
        }

        /// <summary>
        ///   Computes the Kronecker product between two matrices.
        /// </summary>
        /// 
        /// <param name="a">The left matrix a.</param>
        /// <param name="b">The right matrix b.</param>
        /// <param name="result">The matrix <c>R</c> to store the 
        ///   Kronecker product between matrices <c>A</c> and <c>B</c>.</param>
        /// 
        /// <returns>The Kronecker product of the two matrices.</returns>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static int[][] Kronecker(this long[][] a, double[][] b, int[][] result)
        {
            int arows = a.Rows();
            int acols = a.Columns();
            int brows = b.Rows();
            int bcols = b.Columns();

            for (int i = 0; i < arows; i++)
                for (int j = 0; j < acols; j++)
				{
					int aval = (int)a[i][j];
                    for (int k = 0; k < brows; k++)
					{
						double[] brow = b[k];
                        for (int l = 0; l < bcols; l++)
                            result[i * brows + k][j * bcols + l] = (int)(aval * (int)brow[l]);
					}
				}

            return result;
        }

        /// <summary>
        ///   Computes the Kronecker product between two matrices.
        /// </summary>
        /// 
        /// <param name="a">The left matrix a.</param>
        /// <param name="b">The right matrix b.</param>
        /// <param name="result">The matrix <c>R</c> to store the 
        ///   Kronecker product between matrices <c>A</c> and <c>B</c>.</param>
        /// 
        /// <returns>The Kronecker product of the two matrices.</returns>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static int[][] Kronecker(this long[][] a, double[,] b, int[][] result)
        {
            int arows = a.Rows();
            int acols = a.Columns();
            int brows = b.Rows();
            int bcols = b.Columns();

			{
				Span<double> B = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, double>(ref MemoryMarshal.GetArrayDataReference((Array)b)), b.Length);
				for (int i = 0; i < arows; i++)
					for (int j = 0; j < acols; j++)
					{
						int aval = (int)a[i][j];
						int pb = 0;

						for (int k = 0; k < brows; k++)
							for (int l = 0; l < bcols; l++)
								result[i * brows + k][j * bcols + l] = (int)(aval * (int)(B[pb++]));
					}
			}
			    
            return result;
        }

        /// <summary>
        ///   Computes the Kronecker product between two matrices.
        /// </summary>
        /// 
        /// <param name="a">The left matrix a.</param>
        /// <param name="b">The right matrix b.</param>
        /// <param name="result">The matrix <c>R</c> to store the 
        ///   Kronecker product between matrices <c>A</c> and <c>B</c>.</param>
        /// 
        /// <returns>The Kronecker product of the two matrices.</returns>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static int[][] Kronecker(this long[,] a, double[][] b, int[][] result)
        {
            int arows = a.Rows();
            int acols = a.Columns();
            int brows = b.Rows();
            int bcols = b.Columns();

            for (int i = 0; i < arows; i++)
                for (int j = 0; j < acols; j++)
				{
					int aval = (int)a[i, j];
				    for (int k = 0; k < brows; k++)
					{
						double[] brow = b[k];
					    for (int l = 0; l < bcols; l++)
                            result[i * brows + k][j * bcols + l] = (int)(aval * (int)brow[l]);
					}
				}
                
            return result;
        }

