        ///   of the given matrices <c>A</c> and <c>B</c>.</param>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static double[,] DivideByDiagonal(this long[,] a, int[] diagonal, double[,] result)
        {
            int rows = a.Rows();

            {
                Span<long> ptrA = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, long>(ref MemoryMarshal.GetArrayDataReference((Array)a)), a.Length);
                Span<double> ptrR = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, double>(ref MemoryMarshal.GetArrayDataReference((Array)result)), result.Length);
                {
                    int A = 0;
                    int R = 0;
                    for (int i = 0; i < rows; i++)
                        for (int j = 0; j < diagonal.Length; j++)
                            (ptrR[R++]) = (double)((double)(ptrA[A++]) / (double)diagonal[j]);
                }
            }

            return result;
        }

