        public static double[][] DivideByDiagonal(this long[][] a, int[] diagonal, double[][] result)
        {
            for (int i = 0; i < a.Length; i++)
                for (int j = 0; j < diagonal.Length; j++)
                    result[i][j] = (double)((double)(a[i][j]) / (double)diagonal[j]);

            return result;
        }

