        /// <summary>
        ///   Computes the product <c>A'*B</c> of matrix <c>A</c> transposed and matrix <c>B</c>.
        /// </summary>
        /// 
        /// <param name="a">The transposed left matrix <c>A</c>.</param>
        /// <param name="b">The right matrix <c>B</c>.</param>
        /// <param name="result">The matrix <c>R</c> to store the product <c>R = A'*B</c>
        ///   of the given matrices <c>A</c> and <c>B</c>.</param>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static decimal[,] TransposeAndDot(this decimal[,] a, decimal[,] b, decimal[,] result)
        {
            int n = a.Rows();
            int m = a.Columns();
            int p = b.Columns();

#if DEBUG
            if (n != b.Rows() || result.Rows() > m || result.Columns() > p)
                throw new DimensionMismatchException();
            var C = a.Transpose().To<double[,]>().Dot(b.To<double[,]>());
#endif
			{
				Span<decimal> R = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, decimal>(ref MemoryMarshal.GetArrayDataReference((Array)result)), result.Length);
				Span<decimal> B = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, decimal>(ref MemoryMarshal.GetArrayDataReference((Array)b)), b.Length);
				Span<decimal> ptemp = new decimal[p];
				{
					int pr = 0;

					for (int i = 0; i < m; i++)
					{
						int pt = 0;
						int pb = 0;

						for (int k = 0; k < n; k++)
						{
							decimal aval = a[k, i];
							for (int j = 0; j < p; j++)
								ptemp[pt++] += (decimal)((decimal)aval * (decimal)(B[pb++]));
							pt = 0;
						}

						// Update the results row and clear the cache
						for (int j = 0; j < p; j++)
						{
							R[pr++] = (decimal)ptemp[pt];
							ptemp[pt++] = 0;
						}
					}
				}
			}
            
#if DEBUG
            if (!C.IsEqual(result.To<double[,]>(), 1e-4))
                throw new Exception();
#endif

            return result;
        }

