            var t = new decimal[K];

            {
                Span<decimal> B = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, decimal>(ref MemoryMarshal.GetArrayDataReference((Array)b)), b.Length);
                Span<decimal> T = t;
                {
                    for (int j = 0; j < M; j++)
                    {
                        int pb = j;
                        for (int k = 0; k < K; k++)
                        {
                            T[k] = B[pb];
                            pb += stride;
                        }

                        for (int i = 0; i < a.Length; i++)
                        {
                            double s = (double)0;
                            for (int k = 0; k < a[i].Length; k++)
                                s += (double)((double)a[i][k] * (double)T[k]);
                            result[i][j] = (double)s;
                        }
                    }
                }
            }
#if DEBUG
            if (!Matrix.IsEqual(C, result.ToMatrix().To<double[,]>(), 1e-4))
                throw new Exception();
#endif
            return result;
        }

