        /// <summary>
        ///   Gets the outer product (matrix product) between two vectors (a*bT).
        /// </summary>
        /// 
        /// <remarks>
        ///   In linear algebra, the outer product typically refers to the tensor
        ///   product of two vectors. The result of applying the outer product to
        ///   a pair of vectors is a matrix. The name contrasts with the inner product,
        ///   which takes as input a pair of vectors and produces a scalar.
        /// </remarks>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static decimal[,] Outer(this decimal[] a, double[] b, decimal[,] result)
        {
			{
				Span<decimal> R = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, decimal>(ref MemoryMarshal.GetArrayDataReference((Array)result)), result.Length);
				{
					int pr = 0;
					for (int i = 0; i < a.Length; i++)
					{
						decimal x = (decimal)a[i];
						for (int j = 0; j < b.Length; j++)
							R[pr++] = (decimal)(x * (decimal)b[j]);
					}
				}
			}
            
            return result;
        }

        /// <summary>
        ///   Gets the outer product (matrix product) between two vectors (a*bT).
        /// </summary>
        /// 
        /// <remarks>
        ///   In linear algebra, the outer product typically refers to the tensor
        ///   product of two vectors. The result of applying the outer product to
        ///   a pair of vectors is a matrix. The name contrasts with the inner product,
        ///   which takes as input a pair of vectors and produces a scalar.
        /// </remarks>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static decimal[][] Outer(this decimal[] a, double[] b, decimal[][] result)
        {
            for (int i = 0; i < a.Length; i++)
                for (int j = 0; j < b.Length; j++)
                    result[i][j] = (decimal)((decimal)a[i] * (decimal)b[j]);
            return result;
        }

        /// <summary>
        ///   Vector product.
        /// </summary>
        /// 
        /// <remarks>
        ///   The cross product, vector product or Gibbs vector product is a binary operation
        ///   on two vectors in three-dimensional space. It has a vector result, a vector which
        ///   is always perpendicular to both of the vectors being multiplied and the plane
        ///   containing them. It has many applications in mathematics, engineering and physics.
        /// </remarks>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static decimal[] Cross(this decimal[] a, double[] b, decimal[] result)
        {
            result[0] = (decimal)((decimal)a[1]*(decimal)b[2] - (decimal)a[2]*(decimal)b[1]);
            result[1] = (decimal)((decimal)a[2]*(decimal)b[0] - (decimal)a[0]*(decimal)b[2]);
			result[2] = (decimal)((decimal)a[0]*(decimal)b[1] - (decimal)a[1]*(decimal)b[0]);

			return result;
        }






#region Kronecker

        /// <summary>
        ///   Computes the Kronecker product between two matrices.
        /// </summary>
        /// 
        /// <param name="a">The left matrix a.</param>
        /// <param name="b">The right matrix b.</param>
        /// <param name="result">The matrix <c>R</c> to store the 
        ///   Kronecker product between matrices <c>A</c> and <c>B</c>.</param>
        /// 
        /// <returns>The Kronecker product of the two matrices.</returns>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static decimal[,] Kronecker(this decimal[,] a, double[,] b, decimal[,] result)
        {
            int arows = a.Rows();
            int acols = a.Columns();

            int brows = b.Rows();
            int bcols = b.Columns();

            //int crows = arows * brows;
            int ccols = acols * bcols;
            int block = brows * ccols;

            {
                Span<decimal> ptrR = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, decimal>(ref MemoryMarshal.GetArrayDataReference((Array)result)), result.Length);
                Span<decimal> ptrA = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, decimal>(ref MemoryMarshal.GetArrayDataReference((Array)a)), a.Length);
                Span<double> ptrB = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, double>(ref MemoryMarshal.GetArrayDataReference((Array)b)), b.Length);
                {
                    int A = 0;
                    int Ri = 0;

                    for (int i = 0; i < arows; Ri += block, i++)
                    {
                        int Rj = Ri;

                        for (int j = 0; j < acols; j++, Rj += bcols, A++)
                        {
                            int R = Rj;
                            int B = 0;

                            for (int k = 0; k < brows; k++, R += ccols)
                            {
                                for (int l = 0; l < bcols; l++, B++)
                                    ptrR[R + l] = (decimal)((decimal)(ptrA[A]) * (decimal)(ptrB[B]));
                            }
                        }
                    }
                }
            }

            return result;
        }

        /// <summary>
        ///   Computes the Kronecker product between two matrices.
        /// </summary>
        /// 
        /// <param name="a">The left matrix a.</param>
        /// <param name="b">The right matrix b.</param>
        /// <param name="result">The matrix <c>R</c> to store the 
        ///   Kronecker product between matrices <c>A</c> and <c>B</c>.</param>
        /// 
        /// <returns>The Kronecker product of the two matrices.</returns>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static decimal[][] Kronecker(this decimal[][] a, double[][] b, decimal[][] result)
        {
            int arows = a.Rows();
            int acols = a.Columns();
            int brows = b.Rows();
            int bcols = b.Columns();

            for (int i = 0; i < arows; i++)
                for (int j = 0; j < acols; j++)
				{
					decimal aval = (decimal)a[i][j];
                    for (int k = 0; k < brows; k++)
					{
						double[] brow = b[k];
                        for (int l = 0; l < bcols; l++)
                            result[i * brows + k][j * bcols + l] = (decimal)(aval * (decimal)brow[l]);
					}
				}

            return result;
        }

        /// <summary>
        ///   Computes the Kronecker product between two matrices.
        /// </summary>
        /// 
        /// <param name="a">The left matrix a.</param>
        /// <param name="b">The right matrix b.</param>
        /// <param name="result">The matrix <c>R</c> to store the 
        ///   Kronecker product between matrices <c>A</c> and <c>B</c>.</param>
        /// 
        /// <returns>The Kronecker product of the two matrices.</returns>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static decimal[][] Kronecker(this decimal[][] a, double[,] b, decimal[][] result)
        {
            int arows = a.Rows();
            int acols = a.Columns();
            int brows = b.Rows();
            int bcols = b.Columns();

			{
				Span<double> B = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, double>(ref MemoryMarshal.GetArrayDataReference((Array)b)), b.Length);
				for (int i = 0; i < arows; i++)
					for (int j = 0; j < acols; j++)
					{
						decimal aval = (decimal)a[i][j];
						int pb = 0;

						for (int k = 0; k < brows; k++)
							for (int l = 0; l < bcols; l++)
								result[i * brows + k][j * bcols + l] = (decimal)(aval * (decimal)(B[pb++]));
					}
			}
			    
            return result;
        }

        /// <summary>
        ///   Computes the Kronecker product between two matrices.
        /// </summary>
        /// 
        /// <param name="a">The left matrix a.</param>
        /// <param name="b">The right matrix b.</param>
        /// <param name="result">The matrix <c>R</c> to store the 
        ///   Kronecker product between matrices <c>A</c> and <c>B</c>.</param>
        /// 
        /// <returns>The Kronecker product of the two matrices.</returns>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static decimal[][] Kronecker(this decimal[,] a, double[][] b, decimal[][] result)
        {
            int arows = a.Rows();
            int acols = a.Columns();
            int brows = b.Rows();
            int bcols = b.Columns();

            for (int i = 0; i < arows; i++)
                for (int j = 0; j < acols; j++)
				{
					decimal aval = (decimal)a[i, j];
				    for (int k = 0; k < brows; k++)
					{
						double[] brow = b[k];
					    for (int l = 0; l < bcols; l++)
                            result[i * brows + k][j * bcols + l] = (decimal)(aval * (decimal)brow[l]);
					}
				}
                
            return result;
        }

        /// <summary>
        ///   Computes the Kronecker product between two vectors.
        /// </summary>
        /// 
        /// <param name="a">The left vector a.</param>
