                        int pb = j;
                        for (int k = 0; k < K; k++)
                        {
                            T[k] = B[pb];
                            pb += stride;
                        }

                        for (int i = 0; i < a.Length; i++)
                        {
                            decimal s = (decimal)0;
                            for (int k = 0; k < a[i].Length; k++)
                                s += (decimal)((decimal)a[i][k] * (decimal)T[k]);
                            result[i][j] = (decimal)s;
                        }
                    }
                }
            }
#if DEBUG
            if (!Matrix.IsEqual(C, result.ToMatrix().To<double[,]>(), 1e-4))
                throw new Exception();
#endif
            return result;
        }

