        /// <summary>
        ///   Computes the product <c>R = A*B</c> of two matrices <c>A</c>
        ///   and <c>B</c>, storing the result in matrix <c>R</c>.
        /// </summary>
        /// 
        /// <param name="a">The left matrix <c>A</c>.</param>
        /// <param name="b">The right matrix <c>B</c>.</param>
        /// <param name="result">The matrix <c>R</c> to store the product <c>R = A*B</c>
        ///   of the given matrices <c>A</c> and <c>B</c>.</param>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static int[,] Dot(this decimal[,] a, int[,] b, int[,] result)
        {
            int N = result.Rows();
            int K = a.Columns();
            int M = result.Columns();
            int stride = b.Columns();
#if DEBUG
            if (a.Columns() != b.Rows() || result.Rows() > a.Rows() || result.Columns() > b.Columns())
                throw new DimensionMismatchException();

            var C = Matrix.CreateAs(result).To<double[,]>();
            for (int i = 0; i < N; i++)
                for (int j = 0; j < M; j++)
                    for (int k = 0; k < K; k++)
                        C[i, j] += ((double)a[i, k] * (double)b[k, j]);
#endif
            var t = new int[K];

            {
                Span<decimal> A = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, decimal>(ref MemoryMarshal.GetArrayDataReference((Array)a)), a.Length);
                Span<int> B = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, int>(ref MemoryMarshal.GetArrayDataReference((Array)b)), b.Length);
                Span<int> T = t;
                Span<int> R = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, int>(ref MemoryMarshal.GetArrayDataReference((Array)result)), result.Length);
                {
                    for (int j = 0; j < M; j++)
                    {
                        int pb = j;
                        for (int k = 0; k < K; k++)
                        {
                            T[k] = B[pb];
                            pb += stride;
                        }

                        int pa = 0;
                        int pr = j;
                        for (int i = 0; i < N; i++)
                        {
                            int s = (int)0;
                            for (int k = 0; k < K; k++)
                                s += (int)((int)A[pa + k] * (int)T[k]);
                            R[pr] = (int)s;
                            pa += K;
                            pr += M;
                        }
                    }
                }
            }
#if DEBUG
            if (!Matrix.IsEqual(C, result.To<double[,]>(), 1e-4))
                throw new Exception();
#endif
            return result;
        }

