#endif
        public static int[][] Kronecker(this decimal[][] a, float[][] b, int[][] result)
        {
            int arows = a.Rows();
            int acols = a.Columns();
            int brows = b.Rows();
            int bcols = b.Columns();

            for (int i = 0; i < arows; i++)
                for (int j = 0; j < acols; j++)
				{
					double aval = (double)a[i][j];
                    for (int k = 0; k < brows; k++)
					{
						float[] brow = b[k];
                        for (int l = 0; l < bcols; l++)
                            result[i * brows + k][j * bcols + l] = (int)(aval * (double)brow[l]);
					}
				}

            return result;
        }

