#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static byte[,] Dot(this byte[,] a, byte[,] b, byte[,] result)
        {
            int N = result.Rows();
            int K = a.Columns();
            int M = result.Columns();
            int stride = b.Columns();
#if DEBUG
            if (a.Columns() != b.Rows() || result.Rows() > a.Rows() || result.Columns() > b.Columns())
                throw new DimensionMismatchException();

            var C = Matrix.CreateAs(result).To<double[,]>();
            for (int i = 0; i < N; i++)
                for (int j = 0; j < M; j++)
                    for (int k = 0; k < K; k++)
                        C[i, j] += ((double)a[i, k] * (double)b[k, j]);
#endif
            var t = new byte[K];

            {
                Span<byte> A = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, byte>(ref MemoryMarshal.GetArrayDataReference((Array)a)), a.Length);
                Span<byte> B = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, byte>(ref MemoryMarshal.GetArrayDataReference((Array)b)), b.Length);
                Span<byte> T = t;
                Span<byte> R = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, byte>(ref MemoryMarshal.GetArrayDataReference((Array)result)), result.Length);
                {
                    for (int j = 0; j < M; j++)
                    {
                        int pb = j;
                        for (int k = 0; k < K; k++)
                        {
                            T[k] = B[pb];
                            pb += stride;
                        }

                        int pa = 0;
                        int pr = j;
                        for (int i = 0; i < N; i++)
                        {
                            byte s = (byte)0;
                            for (int k = 0; k < K; k++)
                                s += (byte)((byte)A[pa + k] * (byte)T[k]);
                            R[pr] = (byte)s;
                            pa += K;
                            pr += M;
                        }
                    }
                }
            }
#if DEBUG
            if (!Matrix.IsEqual(C, result.To<double[,]>(), 1e-4))
                throw new Exception();
#endif
            return result;
        }

