        /// <summary>
        ///   Multiplies a matrix <c>A</c> and a column vector <c>v</c>,
        ///   giving the product <c>A*v</c>
        /// </summary>
        /// 
        /// <param name="matrix">The matrix <c>A</c>.</param>
        /// <param name="columnVector">The column vector <c>v</c>.</param>
        /// <param name="result">The matrix <c>R</c> to store the product.</param>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static byte[] Dot(this byte[,] matrix, byte[] columnVector, byte[] result)
        {
            int cols = matrix.Columns();
            int rows = matrix.Rows();

#if DEBUG
            if (cols != columnVector.Length || result.Length > rows)
                throw new DimensionMismatchException();
#endif
			{
				Span<byte> a = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, byte>(ref MemoryMarshal.GetArrayDataReference((Array)matrix)), matrix.Length);
				Span<byte> x = columnVector;
				Span<byte> r = result;
				{
					int pa1 = 0;
					int pa2 = cols;
					int pr = 0;

					// Process rows two at a time
					for (int i = 0; i < rows / 2; i++)
					{
						byte sum1 = 0, sum2 = 0;
						int px = 0;

						for (int j = 0; j < cols; j++)
						{
							sum1 += (byte)((byte)(a[pa1++]) * (byte)(x[px]));
							sum2 += (byte)((byte)(a[pa2++]) * (byte)(x[px]));
							px++;
						}

						r[pr++] = (byte)sum1;
						r[pr++] = (byte)sum2;
                    
						// Now we skip a row
						pa1 = pa2;
						pa2 += cols;
					}

					// Process the remainder
					for (int i = 0; i < rows % 2; i++)
					{
						byte sum = 0;
						int px = 0;

						for (int j = 0; j < cols; j++)
							sum += (byte)((byte)(a[pa1++]) * (byte)(x[px++]));

						r[pr] = (byte)sum;
					}
				}
			}

            return result;
        }

