#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static double[] Dot(this byte[] rowVector, byte[,] matrix, double[] result)
        {
#if DEBUG
            if (rowVector.Length != matrix.Rows() || result.Length > matrix.Columns())
                throw new DimensionMismatchException();
#endif
                        int cols = matrix.Columns();
            for (int j = 0; j < cols; j++)
            {
                double s = (double)0;
                for (int k = 0; k < rowVector.Length; k++)
                    s += (double)((double)rowVector[k] * (double)matrix[k, j]);
                result[j] = (double)s;
            }
            return result;
        }

        /// <summary>
        ///   Multiplies a matrix <c>A</c> and a column vector <c>v</c>,
        ///   giving the product <c>A*v</c>
        /// </summary>
        /// 
        /// <param name="matrix">The matrix <c>A</c>.</param>
        /// <param name="columnVector">The column vector <c>v</c>.</param>
        /// <param name="result">The matrix <c>R</c> to store the product.</param>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static double[] Dot(this byte[][] matrix, byte[] columnVector, double[] result)
        {
#if DEBUG
            if (matrix.Columns() != columnVector.Length || result.Length > matrix.Length)
                throw new DimensionMismatchException();
#endif

            for (int i = 0; i < matrix.Length; i++)
            {
                double s = (double)0;
                for (int j = 0; j < columnVector.Length; j++)
                    s += (double)((double)matrix[i][j] * (double)columnVector[j]);
                result[i] = (double)s;
            }
            return result;
        }

        /// <summary>
        ///   Multiplies a matrix <c>A</c> and a column vector <c>v</c>,
        ///   giving the product <c>A*v</c>
        /// </summary>
        /// 
        /// <param name="matrix">The matrix <c>A</c>.</param>
        /// <param name="columnVector">The column vector <c>v</c>.</param>
        /// <param name="result">The matrix <c>R</c> to store the product.</param>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static double[] Dot(this byte[,] matrix, byte[] columnVector, double[] result)
        {
            int cols = matrix.Columns();
            int rows = matrix.Rows();

#if DEBUG
            if (cols != columnVector.Length || result.Length > rows)
                throw new DimensionMismatchException();
#endif
			{
				Span<byte> a = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, byte>(ref MemoryMarshal.GetArrayDataReference((Array)matrix)), matrix.Length);
				Span<byte> x = columnVector;
				Span<double> r = result;
				{
					int pa1 = 0;
					int pa2 = cols;
					int pr = 0;

					// Process rows two at a time
					for (int i = 0; i < rows / 2; i++)
					{
						double sum1 = 0, sum2 = 0;
						int px = 0;

						for (int j = 0; j < cols; j++)
						{
							sum1 += (double)((double)(a[pa1++]) * (double)(x[px]));
							sum2 += (double)((double)(a[pa2++]) * (double)(x[px]));
							px++;
						}

						r[pr++] = (double)sum1;
						r[pr++] = (double)sum2;
                    
						// Now we skip a row
						pa1 = pa2;
						pa2 += cols;
					}

					// Process the remainder
					for (int i = 0; i < rows % 2; i++)
					{
						double sum = 0;
						int px = 0;

						for (int j = 0; j < cols; j++)
							sum += (double)((double)(a[pa1++]) * (double)(x[px++]));

						r[pr] = (double)sum;
					}
				}
			}

            return result;
        }

