                        int pa = 0;
                        int pr = j;
                        for (int i = 0; i < N; i++)
                        {
                            byte s = (byte)0;
                            for (int k = 0; k < K; k++)
                                s += (byte)((byte)A[pa + k] * (byte)T[k]);
                            R[pr] = (byte)s;
                            pa += K;
                            pr += M;
                        }
                    }
                }
            }
#if DEBUG
            if (!Matrix.IsEqual(C, result.To<double[,]>(), 1e-4))
                throw new Exception();
#endif
            return result;
        }

