				Span<int> B = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, int>(ref MemoryMarshal.GetArrayDataReference((Array)b)), b.Length);
				Span<byte> ptemp = new byte[p];
				{
					int pr = 0;

					for (int i = 0; i < m; i++)
					{
						int pt = 0;
						int pb = 0;

						for (int k = 0; k < n; k++)
						{
							byte aval = a[k, i];
							for (int j = 0; j < p; j++)
								ptemp[pt++] += (byte)((byte)aval * (byte)(B[pb++]));
							pt = 0;
						}

						// Update the results row and clear the cache
						for (int j = 0; j < p; j++)
						{
							R[pr++] = (byte)ptemp[pt];
							ptemp[pt++] = 0;
						}
					}
				}
			}
            
#if DEBUG
            if (!C.IsEqual(result.To<double[,]>(), 1e-4))
                throw new Exception();
#endif

            return result;
        }

        /// <summary>
