                    for (int k = 0; k < arow.Length; k++)
                        sum += (double)((double)arow[k] * (double)brow[k]);
                    result[i][j] = (double)sum;
                }
            }
#if DEBUG
            if (!Matrix.IsEqual(C, result.To<double[,]>(), 1e-4))
                throw new Exception();
#endif
            return result;
        }

