        public static byte[][] DivideByDiagonal(this byte[][] a, float[] diagonal, byte[][] result)
        {
            for (int i = 0; i < a.Length; i++)
                for (int j = 0; j < diagonal.Length; j++)
                    result[i][j] = (byte)((double)(a[i][j]) / (double)diagonal[j]);

            return result;
        }

