					for (int k = 0; k < t.Length; k++)
						t[k] = b[k][j];

					int pa = 0;
					for (int i = 0; i < N; i++)
					{
						double s = (double)0;
						for (int k = 0; k < t.Length; k++)
							s += (double)((double)(A[pa++]) * (double)t[k]);
						result[i][j] = (float)s;
