#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static float[] Dot(this byte[] rowVector, float[][] matrix, float[] result)
        {
#if DEBUG
            if (rowVector.Length != matrix.Length || result.Length > matrix.Columns())
                throw new DimensionMismatchException();
#endif
            for (int j = 0; j < result.Length; j++)
            {
                double s = (double)0;
                for (int k = 0; k < rowVector.Length; k++)
                    s += (double)((double)rowVector[k] * (double)matrix[k][j]);
                result[j] = (float)s;
            }

            return result;
        }

