#region dot

        /// <summary>
        ///   Computes the product <c>R = A*B</c> of two matrices <c>A</c>
        ///   and <c>B</c>, storing the result in matrix <c>R</c>.
        /// </summary>
        /// 
        /// <param name="a">The left matrix <c>A</c>.</param>
        /// <param name="b">The right matrix <c>B</c>.</param>
        /// <param name="result">The matrix <c>R</c> to store the product <c>R = A*B</c>
        ///   of the given matrices <c>A</c> and <c>B</c>.</param>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static double[,] Dot(this short[,] a, short[,] b, double[,] result)
        {
            int N = result.Rows();
            int K = a.Columns();
            int M = result.Columns();
            int stride = b.Columns();
#if DEBUG
            if (a.Columns() != b.Rows() || result.Rows() > a.Rows() || result.Columns() > b.Columns())
                throw new DimensionMismatchException();

            var C = Matrix.CreateAs(result).To<double[,]>();
            for (int i = 0; i < N; i++)
                for (int j = 0; j < M; j++)
                    for (int k = 0; k < K; k++)
                        C[i, j] += ((double)a[i, k] * (double)b[k, j]);
#endif
            var t = new short[K];

            {
                Span<short> A = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, short>(ref MemoryMarshal.GetArrayDataReference((Array)a)), a.Length);
                Span<short> B = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, short>(ref MemoryMarshal.GetArrayDataReference((Array)b)), b.Length);
                Span<short> T = t;
                Span<double> R = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, double>(ref MemoryMarshal.GetArrayDataReference((Array)result)), result.Length);
                {
                    for (int j = 0; j < M; j++)
                    {
                        int pb = j;
                        for (int k = 0; k < K; k++)
                        {
                            T[k] = B[pb];
                            pb += stride;
                        }

                        int pa = 0;
                        int pr = j;
                        for (int i = 0; i < N; i++)
                        {
                            double s = (double)0;
                            for (int k = 0; k < K; k++)
                                s += (double)((double)A[pa + k] * (double)T[k]);
                            R[pr] = (double)s;
                            pa += K;
                            pr += M;
                        }
                    }
                }
            }
#if DEBUG
            if (!Matrix.IsEqual(C, result.To<double[,]>(), 1e-4))
                throw new Exception();
#endif
            return result;
        }

        /// <summary>
        ///   Computes the product <c>R = A*B</c> of two matrices <c>A</c>
        ///   and <c>B</c>, storing the result in matrix <c>R</c>.
        /// </summary>
        /// 
        /// <param name="a">The left matrix <c>A</c>.</param>
        /// <param name="b">The right matrix <c>B</c>.</param>
        /// <param name="result">The matrix <c>R</c> to store the product.</param>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static double[][] Dot(this short[][] a, short[][] b, double[][] result)
        {
#if DEBUG
            if (a.Columns() != b.Length || result.Length > a.Length || result.Columns() > b.Columns())
                throw new DimensionMismatchException();
            var C = Jagged.CreateAs(result).To<double[,]>();
            C = Dot(a.ToMatrix().To<double[,]>(), b.ToMatrix().To<double[,]>(), C);
#endif
            int N = result.Length;
            int K = a.Columns();
            int M = result.Columns();

            var t = new short[K];

            for (int j = 0; j < M; j++)
            {
                for (int k = 0; k < b.Length; k++)
                    t[k] = b[k][j];

                for (int i = 0; i < a.Length; i++)
                {
                    double s = (double)0;
                    for (int k = 0; k < t.Length; k++)
                        s += (double)((double)a[i][k] * (double)t[k]);
                    result[i][j] = (double)s;
                }
            }
#if DEBUG
            if (!Matrix.IsEqual(C, result.ToMatrix().To<double[,]>(), 1e-4))
                throw new Exception();
#endif
            return result;
        }

        /// <summary>
        ///   Computes the product <c>R = A*B</c> of two matrices <c>A</c>
        ///   and <c>B</c>, storing the result in matrix <c>R</c>.
        /// </summary>
        /// 
        /// <param name="a">The left matrix <c>A</c>.</param>
        /// <param name="b">The right matrix <c>B</c>.</param>
        /// <param name="result">The matrix <c>R</c> to store the product.</param>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static double[][] Dot(this short[][] a, short[,] b, double[][] result)
        {
#if DEBUG
            if (a.Columns() != b.Rows() || result.Length > a.Length || result.Columns() > b.Columns())
                throw new DimensionMismatchException();
            var C = Matrix.CreateAs(result).To<double[,]>();
            C = Dot(a.ToMatrix().To<double[,]>(), b.To<double[,]>(), C);
#endif
            int N = result.Length;
            int K = a.Columns();
            int M = result.Columns();
            int stride = b.Columns();
            var t = new short[K];

            {
                Span<short> B = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, short>(ref MemoryMarshal.GetArrayDataReference((Array)b)), b.Length);
                Span<short> T = t;
                {
                    for (int j = 0; j < M; j++)
                    {
                        int pb = j;
                        for (int k = 0; k < K; k++)
                        {
                            T[k] = B[pb];
                            pb += stride;
                        }

                        for (int i = 0; i < a.Length; i++)
                        {
                            double s = (double)0;
                            for (int k = 0; k < a[i].Length; k++)
                                s += (double)((double)a[i][k] * (double)T[k]);
                            result[i][j] = (double)s;
                        }
                    }
                }
            }
#if DEBUG
            if (!Matrix.IsEqual(C, result.ToMatrix().To<double[,]>(), 1e-4))
                throw new Exception();
#endif
            return result;
        }

