            var t = new double[K];

            for (int j = 0; j < M; j++)
            {
                for (int k = 0; k < b.Length; k++)
                    t[k] = b[k][j];

                for (int i = 0; i < a.Length; i++)
                {
                    short s = (short)0;
                    for (int k = 0; k < t.Length; k++)
                        s += (short)((short)a[i][k] * (short)t[k]);
                    result[i][j] = (short)s;
                }
            }
#if DEBUG
            if (!Matrix.IsEqual(C, result.ToMatrix().To<double[,]>(), 1e-4))
                throw new Exception();
#endif
            return result;
        }

