                        for (int i = 0; i < a.Length; i++)
                        {
                            short s = (short)0;
                            for (int k = 0; k < a[i].Length; k++)
                                s += (short)((short)a[i][k] * (short)T[k]);
                            result[i][j] = (short)s;
                        }
                    }
                }
            }
#if DEBUG
            if (!Matrix.IsEqual(C, result.ToMatrix().To<double[,]>(), 1e-4))
                throw new Exception();
#endif
            return result;
        }

