        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static short[] Dot(this short[] rowVector, int[,] matrix, short[] result)
        {
#if DEBUG
            if (rowVector.Length != matrix.Rows() || result.Length > matrix.Columns())
                throw new DimensionMismatchException();
#endif
                        int cols = matrix.Columns();
            for (int j = 0; j < cols; j++)
            {
                short s = (short)0;
                for (int k = 0; k < rowVector.Length; k++)
                    s += (short)((short)rowVector[k] * (short)matrix[k, j]);
                result[j] = (short)s;
            }
            return result;
        }

        /// <summary>
        ///   Multiplies a matrix <c>A</c> and a column vector <c>v</c>,
        ///   giving the product <c>A*v</c>
        /// </summary>
        /// 
        /// <param name="matrix">The matrix <c>A</c>.</param>
        /// <param name="columnVector">The column vector <c>v</c>.</param>
        /// <param name="result">The matrix <c>R</c> to store the product.</param>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static short[] Dot(this short[][] matrix, int[] columnVector, short[] result)
        {
#if DEBUG
            if (matrix.Columns() != columnVector.Length || result.Length > matrix.Length)
                throw new DimensionMismatchException();
#endif

            for (int i = 0; i < matrix.Length; i++)
            {
                short s = (short)0;
                for (int j = 0; j < columnVector.Length; j++)
                    s += (short)((short)matrix[i][j] * (short)columnVector[j]);
                result[i] = (short)s;
            }
            return result;
        }

        /// <summary>
        ///   Multiplies a matrix <c>A</c> and a column vector <c>v</c>,
        ///   giving the product <c>A*v</c>
        /// </summary>
        /// 
        /// <param name="matrix">The matrix <c>A</c>.</param>
        /// <param name="columnVector">The column vector <c>v</c>.</param>
        /// <param name="result">The matrix <c>R</c> to store the product.</param>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static short[] Dot(this short[,] matrix, int[] columnVector, short[] result)
        {
            int cols = matrix.Columns();
            int rows = matrix.Rows();

#if DEBUG
            if (cols != columnVector.Length || result.Length > rows)
                throw new DimensionMismatchException();
#endif
			{
				Span<short> a = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, short>(ref MemoryMarshal.GetArrayDataReference((Array)matrix)), matrix.Length);
				Span<int> x = columnVector;
				Span<short> r = result;
				{
					int pa1 = 0;
					int pa2 = cols;
					int pr = 0;

					// Process rows two at a time
					for (int i = 0; i < rows / 2; i++)
					{
						short sum1 = 0, sum2 = 0;
						int px = 0;

						for (int j = 0; j < cols; j++)
						{
							sum1 += (short)((short)(a[pa1++]) * (short)(x[px]));
							sum2 += (short)((short)(a[pa2++]) * (short)(x[px]));
							px++;
						}

						r[pr++] = (short)sum1;
						r[pr++] = (short)sum2;
                    
						// Now we skip a row
						pa1 = pa2;
						pa2 += cols;
					}

					// Process the remainder
					for (int i = 0; i < rows % 2; i++)
					{
						short sum = 0;
						int px = 0;

						for (int j = 0; j < cols; j++)
							sum += (short)((short)(a[pa1++]) * (short)(x[px++]));

						r[pr] = (short)sum;
					}
				}
			}

            return result;
        }

