#endif
        public static int[] Dot(this short[,] matrix, int[] columnVector, int[] result)
        {
            int cols = matrix.Columns();
            int rows = matrix.Rows();

#if DEBUG
            if (cols != columnVector.Length || result.Length > rows)
                throw new DimensionMismatchException();
#endif
			{
				Span<short> a = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, short>(ref MemoryMarshal.GetArrayDataReference((Array)matrix)), matrix.Length);
				Span<int> x = columnVector;
				Span<int> r = result;
				{
					int pa1 = 0;
					int pa2 = cols;
					int pr = 0;

					// Process rows two at a time
					for (int i = 0; i < rows / 2; i++)
					{
						int sum1 = 0, sum2 = 0;
						int px = 0;

						for (int j = 0; j < cols; j++)
						{
							sum1 += (int)((int)(a[pa1++]) * (int)(x[px]));
							sum2 += (int)((int)(a[pa2++]) * (int)(x[px]));
							px++;
						}

						r[pr++] = (int)sum1;
						r[pr++] = (int)sum2;
                    
						// Now we skip a row
						pa1 = pa2;
						pa2 += cols;
					}

					// Process the remainder
					for (int i = 0; i < rows % 2; i++)
					{
						int sum = 0;
						int px = 0;

						for (int j = 0; j < cols; j++)
							sum += (int)((int)(a[pa1++]) * (int)(x[px++]));

						r[pr] = (int)sum;
					}
				}
			}

            return result;
        }

        /// <summary>
        ///   Computes the product <c>R = A*B</c> of two matrices <c>A</c>
        ///   and <c>B</c>, storing the result in matrix <c>R</c>.
        /// </summary>
        /// 
        /// <param name="rowVector">The left matrix <c>A</c>.</param>
        /// <param name="matrix">The right matrix <c>B</c>.</param>
        /// <param name="result">The matrix <c>R</c> to store the product.</param>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static int[] Dot(this short[] rowVector, int[][] matrix, int[] result)
        {
#if DEBUG
            if (rowVector.Length != matrix.Length || result.Length > matrix.Columns())
                throw new DimensionMismatchException();
#endif
            for (int j = 0; j < result.Length; j++)
            {
                int s = (int)0;
                for (int k = 0; k < rowVector.Length; k++)
                    s += (int)((int)rowVector[k] * (int)matrix[k][j]);
                result[j] = (int)s;
            }

            return result;
        }

