#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static double[,] DotWithTransposed(this short[,] a, int[,] b, double[,] result)
        {
#if DEBUG
            if (a.Columns() != b.Columns() || result.Rows() > a.Rows() || result.Columns() > b.Rows())
                throw new DimensionMismatchException();
            var C = Matrix.CreateAs(result).To<double[,]>();
            C = Dot(a.To<double[,]>(), b.Transpose().To<double[,]>(), C);
#endif
            int n = a.Columns();
            int m = a.Rows();
            int p = b.Rows();

            {
                Span<short> A = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, short>(ref MemoryMarshal.GetArrayDataReference((Array)a)), a.Length);
                Span<int> B = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, int>(ref MemoryMarshal.GetArrayDataReference((Array)b)), b.Length);
                Span<double> R = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, double>(ref MemoryMarshal.GetArrayDataReference((Array)result)), result.Length);
                {
                    int pr = 0;
                    for (int i = 0; i < m; i++)
                    {
                        int pb = 0;
                        for (int j = 0; j < p; j++, pr++)
                        {
                            int pa = n * i;

                            double s = (double)0;
                            for (int k = 0; k < n; k++)
                                s += (double)((double)(A[pa++]) * (double)(B[pb++]));
                            R[pr] = (double)s;
                        }
                    }
                }
            }
#if DEBUG
            if (!Matrix.IsEqual(C, result.To<double[,]>(), 1e-4))
                throw new Exception();
#endif
            return result;
        }

