        public static short[][] Dot(this short[][] a, float[,] b, short[][] result)
        {
#if DEBUG
            if (a.Columns() != b.Rows() || result.Length > a.Length || result.Columns() > b.Columns())
                throw new DimensionMismatchException();
            var C = Matrix.CreateAs(result).To<double[,]>();
            C = Dot(a.ToMatrix().To<double[,]>(), b.To<double[,]>(), C);
#endif
            int N = result.Length;
            int K = a.Columns();
            int M = result.Columns();
            int stride = b.Columns();
            var t = new float[K];

            {
                Span<float> B = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, float>(ref MemoryMarshal.GetArrayDataReference((Array)b)), b.Length);
                Span<float> T = t;
                {
                    for (int j = 0; j < M; j++)
                    {
                        int pb = j;
                        for (int k = 0; k < K; k++)
                        {
                            T[k] = B[pb];
                            pb += stride;
                        }

                        for (int i = 0; i < a.Length; i++)
                        {
                            double s = (double)0;
                            for (int k = 0; k < a[i].Length; k++)
                                s += (double)((double)a[i][k] * (double)T[k]);
                            result[i][j] = (short)s;
                        }
                    }
                }
            }
#if DEBUG
            if (!Matrix.IsEqual(C, result.ToMatrix().To<double[,]>(), 1e-4))
                throw new Exception();
#endif
            return result;
        }

