        /// <summary>
        ///   Computes the product <c>A'*B</c> of matrix <c>A</c> transposed and matrix <c>B</c>.
        /// </summary>
        /// 
        /// <param name="a">The transposed left matrix <c>A</c>.</param>
        /// <param name="b">The right matrix <c>B</c>.</param>
        /// <param name="result">The matrix <c>R</c> to store the product <c>R = A'*B</c>
        ///   of the given matrices <c>A</c> and <c>B</c>.</param>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static sbyte[,] TransposeAndDot(this sbyte[,] a, sbyte[,] b, sbyte[,] result)
        {
            int n = a.Rows();
            int m = a.Columns();
            int p = b.Columns();

#if DEBUG
            if (n != b.Rows() || result.Rows() > m || result.Columns() > p)
                throw new DimensionMismatchException();
            var C = a.Transpose().To<double[,]>().Dot(b.To<double[,]>());
#endif
			{
				Span<sbyte> R = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, sbyte>(ref MemoryMarshal.GetArrayDataReference((Array)result)), result.Length);
				Span<sbyte> B = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, sbyte>(ref MemoryMarshal.GetArrayDataReference((Array)b)), b.Length);
				Span<sbyte> ptemp = new sbyte[p];
				{
					int pr = 0;

					for (int i = 0; i < m; i++)
					{
						int pt = 0;
						int pb = 0;

						for (int k = 0; k < n; k++)
						{
							sbyte aval = a[k, i];
							for (int j = 0; j < p; j++)
								ptemp[pt++] += (sbyte)((sbyte)aval * (sbyte)(B[pb++]));
							pt = 0;
						}

						// Update the results row and clear the cache
						for (int j = 0; j < p; j++)
						{
							R[pr++] = (sbyte)ptemp[pt];
							ptemp[pt++] = 0;
						}
					}
				}
			}
            
#if DEBUG
            if (!C.IsEqual(result.To<double[,]>(), 1e-4))
                throw new Exception();
#endif

            return result;
        }

        /// <summary>
        ///   Computes the product <c>A'*B</c> of matrix <c>A</c> transposed and matrix <c>B</c>.
        /// </summary>
        /// 
        /// <param name="a">The transposed left matrix <c>A</c>.</param>
        /// <param name="b">The right matrix <c>B</c>.</param>
        /// <param name="result">The matrix <c>R</c> to store the product <c>R = A'*B</c>
        ///   of the given matrices <c>A</c> and <c>B</c>.</param>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static sbyte[][] TransposeAndDot(this sbyte[][] a, sbyte[][] b, sbyte[][] result)
        {
#if DEBUG
            if (a.Length != b.Length || result.Length > a.Columns() || result.Columns() > b.Columns())
                throw new DimensionMismatchException();
            var C = Dot(a.Transpose().To<double[,]>(), b.To<double[,]>());
#endif
            int n = a.Length;
            int m = a.Columns();
            int p = b.Columns();

            var Bcolj = new sbyte[n];
            for (int i = 0; i < p; i++)
            {
                for (int k = 0; k < b.Length; k++)
                    Bcolj[k] = b[k][i];

                for (int j = 0; j < m; j++)
