                    sbyte s = (sbyte)0;
                    for (int k = 0; k < Bcolj.Length; k++)
                        s += (sbyte)((sbyte)a[k][j] * (sbyte)Bcolj[k]);
                    result[j][i] = (sbyte)s;
                }
            }
#if DEBUG
            if (!Matrix.IsEqual(C, result.To<double[,]>(), 1e-4))
                throw new Exception();
#endif
            return result;
        }


       

