#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static double[,] DivideByDiagonal(this sbyte[,] a, sbyte[] diagonal, double[,] result)
        {
