        ///   of the given matrices <c>A</c> and <c>B</c>.</param>
        ///    
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static sbyte[,] DotWithTransposed(this sbyte[,] a, double[,] b, sbyte[,] result)
        {
#if DEBUG
            if (a.Columns() != b.Columns() || result.Rows() > a.Rows() || result.Columns() > b.Rows())
                throw new DimensionMismatchException();
            var C = Matrix.CreateAs(result).To<double[,]>();
            C = Dot(a.To<double[,]>(), b.Transpose().To<double[,]>(), C);
#endif
            int n = a.Columns();
            int m = a.Rows();
            int p = b.Rows();

            {
                Span<sbyte> A = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, sbyte>(ref MemoryMarshal.GetArrayDataReference((Array)a)), a.Length);
                Span<double> B = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, double>(ref MemoryMarshal.GetArrayDataReference((Array)b)), b.Length);
                Span<sbyte> R = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, sbyte>(ref MemoryMarshal.GetArrayDataReference((Array)result)), result.Length);
                {
                    int pr = 0;
                    for (int i = 0; i < m; i++)
                    {
                        int pb = 0;
                        for (int j = 0; j < p; j++, pr++)
                        {
                            int pa = n * i;

                            sbyte s = (sbyte)0;
                            for (int k = 0; k < n; k++)
                                s += (sbyte)((sbyte)(A[pa++]) * (sbyte)(B[pb++]));
                            R[pr] = (sbyte)s;
                        }
                    }
                }
            }
#if DEBUG
            if (!Matrix.IsEqual(C, result.To<double[,]>(), 1e-4))
                throw new Exception();
#endif
            return result;
        }

