        /// </remarks>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static sbyte[][] Outer(this sbyte[] a, double[] b, sbyte[][] result)
        {
            for (int i = 0; i < a.Length; i++)
                for (int j = 0; j < b.Length; j++)
                    result[i][j] = (sbyte)((sbyte)a[i] * (sbyte)b[j]);
            return result;
        }

        /// <summary>
        ///   Vector product.
        /// </summary>
        /// 
        /// <remarks>
        ///   The cross product, vector product or Gibbs vector product is a binary operation
        ///   on two vectors in three-dimensional space. It has a vector result, a vector which
        ///   is always perpendicular to both of the vectors being multiplied and the plane
        ///   containing them. It has many applications in mathematics, engineering and physics.
        /// </remarks>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static sbyte[] Cross(this sbyte[] a, double[] b, sbyte[] result)
        {
            result[0] = (sbyte)((sbyte)a[1]*(sbyte)b[2] - (sbyte)a[2]*(sbyte)b[1]);
            result[1] = (sbyte)((sbyte)a[2]*(sbyte)b[0] - (sbyte)a[0]*(sbyte)b[2]);
			result[2] = (sbyte)((sbyte)a[0]*(sbyte)b[1] - (sbyte)a[1]*(sbyte)b[0]);

			return result;
        }






#region Kronecker

        /// <summary>
        ///   Computes the Kronecker product between two matrices.
        /// </summary>
        /// 
        /// <param name="a">The left matrix a.</param>
        /// <param name="b">The right matrix b.</param>
        /// <param name="result">The matrix <c>R</c> to store the 
        ///   Kronecker product between matrices <c>A</c> and <c>B</c>.</param>
        /// 
        /// <returns>The Kronecker product of the two matrices.</returns>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static sbyte[,] Kronecker(this sbyte[,] a, double[,] b, sbyte[,] result)
        {
            int arows = a.Rows();
            int acols = a.Columns();

            int brows = b.Rows();
            int bcols = b.Columns();

            //int crows = arows * brows;
            int ccols = acols * bcols;
            int block = brows * ccols;

            {
                Span<sbyte> ptrR = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, sbyte>(ref MemoryMarshal.GetArrayDataReference((Array)result)), result.Length);
                Span<sbyte> ptrA = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, sbyte>(ref MemoryMarshal.GetArrayDataReference((Array)a)), a.Length);
                Span<double> ptrB = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, double>(ref MemoryMarshal.GetArrayDataReference((Array)b)), b.Length);
                {
                    int A = 0;
                    int Ri = 0;

                    for (int i = 0; i < arows; Ri += block, i++)
                    {
                        int Rj = Ri;

                        for (int j = 0; j < acols; j++, Rj += bcols, A++)
                        {
                            int R = Rj;
                            int B = 0;

                            for (int k = 0; k < brows; k++, R += ccols)
                            {
                                for (int l = 0; l < bcols; l++, B++)
                                    ptrR[R + l] = (sbyte)((sbyte)(ptrA[A]) * (sbyte)(ptrB[B]));
                            }
                        }
                    }
                }
            }

            return result;
        }

        /// <summary>
        ///   Computes the Kronecker product between two matrices.
        /// </summary>
        /// 
        /// <param name="a">The left matrix a.</param>
        /// <param name="b">The right matrix b.</param>
        /// <param name="result">The matrix <c>R</c> to store the 
        ///   Kronecker product between matrices <c>A</c> and <c>B</c>.</param>
        /// 
        /// <returns>The Kronecker product of the two matrices.</returns>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static sbyte[][] Kronecker(this sbyte[][] a, double[][] b, sbyte[][] result)
        {
            int arows = a.Rows();
            int acols = a.Columns();
            int brows = b.Rows();
            int bcols = b.Columns();

            for (int i = 0; i < arows; i++)
                for (int j = 0; j < acols; j++)
				{
					sbyte aval = (sbyte)a[i][j];
                    for (int k = 0; k < brows; k++)
					{
						double[] brow = b[k];
                        for (int l = 0; l < bcols; l++)
                            result[i * brows + k][j * bcols + l] = (sbyte)(aval * (sbyte)brow[l]);
					}
				}

            return result;
        }

        /// <summary>
        ///   Computes the Kronecker product between two matrices.
        /// </summary>
        /// 
        /// <param name="a">The left matrix a.</param>
        /// <param name="b">The right matrix b.</param>
        /// <param name="result">The matrix <c>R</c> to store the 
        ///   Kronecker product between matrices <c>A</c> and <c>B</c>.</param>
        /// 
        /// <returns>The Kronecker product of the two matrices.</returns>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static sbyte[][] Kronecker(this sbyte[][] a, double[,] b, sbyte[][] result)
        {
            int arows = a.Rows();
            int acols = a.Columns();
            int brows = b.Rows();
            int bcols = b.Columns();

			{
				Span<double> B = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, double>(ref MemoryMarshal.GetArrayDataReference((Array)b)), b.Length);
				for (int i = 0; i < arows; i++)
					for (int j = 0; j < acols; j++)
					{
						sbyte aval = (sbyte)a[i][j];
						int pb = 0;

						for (int k = 0; k < brows; k++)
							for (int l = 0; l < bcols; l++)
								result[i * brows + k][j * bcols + l] = (sbyte)(aval * (sbyte)(B[pb++]));
					}
			}
			    
            return result;
        }

        /// <summary>
        ///   Computes the Kronecker product between two matrices.
        /// </summary>
        /// 
        /// <param name="a">The left matrix a.</param>
        /// <param name="b">The right matrix b.</param>
        /// <param name="result">The matrix <c>R</c> to store the 
        ///   Kronecker product between matrices <c>A</c> and <c>B</c>.</param>
        /// 
        /// <returns>The Kronecker product of the two matrices.</returns>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static sbyte[][] Kronecker(this sbyte[,] a, double[][] b, sbyte[][] result)
        {
            int arows = a.Rows();
            int acols = a.Columns();
            int brows = b.Rows();
            int bcols = b.Columns();

            for (int i = 0; i < arows; i++)
                for (int j = 0; j < acols; j++)
				{
					sbyte aval = (sbyte)a[i, j];
				    for (int k = 0; k < brows; k++)
					{
						double[] brow = b[k];
					    for (int l = 0; l < bcols; l++)
                            result[i * brows + k][j * bcols + l] = (sbyte)(aval * (sbyte)brow[l]);
					}
				}
                
            return result;
        }

        /// <summary>
        ///   Computes the Kronecker product between two vectors.
        /// </summary>
        /// 
        /// <param name="a">The left vector a.</param>
        /// <param name="b">The right vector b.</param>
        /// <param name="result">The matrix <c>R</c> to store the 
