			{
				Span<sbyte> R = result;
				{
					int pr = 0;
					for (int i = 0; i < a.Length; i++)
					{
						sbyte x = (sbyte)a[i];
						for (int j = 0; j < b.Length; j++)
							R[pr++] = (sbyte)(x * (sbyte)b[j]);
					}
				}
			}
            
            return result;
        }

