#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static double[] TransposeAndDot(this sbyte[][] matrix, double[] columnVector, double[] result)
        {
