#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static sbyte[,] Dot(this sbyte[,] a, int[,] b, sbyte[,] result)
        {
            int N = result.Rows();
            int K = a.Columns();
            int M = result.Columns();
            int stride = b.Columns();
#if DEBUG
            if (a.Columns() != b.Rows() || result.Rows() > a.Rows() || result.Columns() > b.Columns())
                throw new DimensionMismatchException();

            var C = Matrix.CreateAs(result).To<double[,]>();
            for (int i = 0; i < N; i++)
                for (int j = 0; j < M; j++)
                    for (int k = 0; k < K; k++)
                        C[i, j] += ((double)a[i, k] * (double)b[k, j]);
#endif
            var t = new int[K];

            {
                Span<sbyte> A = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, sbyte>(ref MemoryMarshal.GetArrayDataReference((Array)a)), a.Length);
                Span<int> B = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, int>(ref MemoryMarshal.GetArrayDataReference((Array)b)), b.Length);
                Span<int> T = t;
                Span<sbyte> R = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, sbyte>(ref MemoryMarshal.GetArrayDataReference((Array)result)), result.Length);
                {
                    for (int j = 0; j < M; j++)
                    {
                        int pb = j;
                        for (int k = 0; k < K; k++)
                        {
                            T[k] = B[pb];
                            pb += stride;
                        }

                        int pa = 0;
                        int pr = j;
                        for (int i = 0; i < N; i++)
                        {
                            sbyte s = (sbyte)0;
                            for (int k = 0; k < K; k++)
                                s += (sbyte)((sbyte)A[pa + k] * (sbyte)T[k]);
                            R[pr] = (sbyte)s;
