        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
		public static int[] Kronecker(this sbyte[] a, int[] b, int[] result)
		{
			{
				Span<int> R = result;
				{
					int pr = 0;
					for (int i = 0; i < a.Length; i++)
					{
						int x = (int)a[i];
						for (int j = 0; j < b.Length; j++)
