        /// <param name="result">The matrix <c>R</c> to store the product <c>R = A*B'</c>
        ///   of the given matrices <c>A</c> and <c>B</c>.</param>
        ///    
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static double[,] DotWithTransposed(this sbyte[,] a, int[,] b, double[,] result)
        {
#if DEBUG
            if (a.Columns() != b.Columns() || result.Rows() > a.Rows() || result.Columns() > b.Rows())
                throw new DimensionMismatchException();
            var C = Matrix.CreateAs(result).To<double[,]>();
            C = Dot(a.To<double[,]>(), b.Transpose().To<double[,]>(), C);
#endif
            int n = a.Columns();
            int m = a.Rows();
            int p = b.Rows();

            {
                Span<sbyte> A = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, sbyte>(ref MemoryMarshal.GetArrayDataReference((Array)a)), a.Length);
                Span<int> B = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, int>(ref MemoryMarshal.GetArrayDataReference((Array)b)), b.Length);
                Span<double> R = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, double>(ref MemoryMarshal.GetArrayDataReference((Array)result)), result.Length);
                {
                    int pr = 0;
                    for (int i = 0; i < m; i++)
                    {
                        int pb = 0;
                        for (int j = 0; j < p; j++, pr++)
                        {
                            int pa = n * i;

                            double s = (double)0;
                            for (int k = 0; k < n; k++)
                                s += (double)((double)(A[pa++]) * (double)(B[pb++]));
                            R[pr] = (double)s;
                        }
                    }
                }
            }
#if DEBUG
            if (!Matrix.IsEqual(C, result.To<double[,]>(), 1e-4))
                throw new Exception();
#endif
            return result;
        }

        /// <summary>
        ///   Computes the product <c>A*B'</c> of matrix <c>A</c> and
        ///   transpose of <c>B</c>, storing the result in matrix <c>R</c>.
        /// </summary>
        /// 
        /// <param name="a">The left matrix <c>A</c>.</param>
        /// <param name="b">The transposed right matrix <c>B</c>.</param>
        /// <param name="result">The matrix <c>R</c> to store the product <c>R = A*B'</c>
        ///   of the given matrices <c>A</c> and <c>B</c>.</param>
        ///    
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static double[][] DotWithTransposed(this sbyte[][] a, int[,] b, double[][] result)
        {
#if DEBUG
            if (a.Columns() != b.Columns() || result.Rows() > a.Rows() || result.Columns() > b.Rows())
                throw new DimensionMismatchException();
            var C = Matrix.CreateAs(result).To<double[,]>();
            C = Dot(a.To<double[,]>(), b.Transpose().To<double[,]>(), C);
#endif
            int n = b.Rows();

			{
				Span<int> B = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, int>(ref MemoryMarshal.GetArrayDataReference((Array)b)), b.Length);
				for (int i = 0; i < a.Length; i++)
				{
					int pb = 0;
					sbyte[] arow = a[i];
					for (int j = 0; j < n; j++)
					{
						double sum = 0;
