#endif
			{
				Span<sbyte> a = MemoryMarshal.CreateSpan(ref Unsafe.As<byte, sbyte>(ref MemoryMarshal.GetArrayDataReference((Array)matrix)), matrix.Length);
				Span<float> x = columnVector;
				Span<float> r = result;
				{
					int pa1 = 0;
					int pa2 = cols;
					int pr = 0;

					// Process rows two at a time
					for (int i = 0; i < rows / 2; i++)
					{
						double sum1 = 0, sum2 = 0;
						int px = 0;

						for (int j = 0; j < cols; j++)
						{
							sum1 += (double)((double)(a[pa1++]) * (double)(x[px]));
							sum2 += (double)((double)(a[pa2++]) * (double)(x[px]));
							px++;
						}

						r[pr++] = (float)sum1;
						r[pr++] = (float)sum2;
                    
						// Now we skip a row
						pa1 = pa2;
						pa2 += cols;
					}

					// Process the remainder
					for (int i = 0; i < rows % 2; i++)
					{
						double sum = 0;
						int px = 0;

						for (int j = 0; j < cols; j++)
							sum += (double)((double)(a[pa1++]) * (double)(x[px++]));

						r[pr] = (float)sum;
					}
				}
			}

            return result;
        }

        /// <summary>
        ///   Computes the product <c>R = A*B</c> of two matrices <c>A</c>
        ///   and <c>B</c>, storing the result in matrix <c>R</c>.
        /// </summary>
        /// 
        /// <param name="rowVector">The left matrix <c>A</c>.</param>
        /// <param name="matrix">The right matrix <c>B</c>.</param>
        /// <param name="result">The matrix <c>R</c> to store the product.</param>
        /// 
#if NET45 || NET46 || NET462 || NETSTANDARD
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
#endif
        public static float[] Dot(this sbyte[] rowVector, float[][] matrix, float[] result)
        {
#if DEBUG
            if (rowVector.Length != matrix.Length || result.Length > matrix.Columns())
                throw new DimensionMismatchException();
#endif
            for (int j = 0; j < result.Length; j++)
            {
                double s = (double)0;
                for (int k = 0; k < rowVector.Length; k++)
                    s += (double)((double)rowVector[k] * (double)matrix[k][j]);
                result[j] = (float)s;
            }

            return result;
        }

