                throw new DimensionMismatchException();
#endif
            for (int j = 0; j < result.Length; j++)
            {
                double s = (double)0;
                for (int k = 0; k < rowVector.Length; k++)
                    s += (double)((double)rowVector[k] * (double)matrix[k][j]);
                result[j] = (double)s;
            }

            return result;
        }

